'use strict';
(()=>{
 const $=id=>document.getElementById(id),kind=document.body.dataset.game,{initial,reduce,done}=window.LittlePlay;
 let state=initial(kind),muted=false,context=null,drag=null,swipe=null,suppressClick=false,lastVoice='';
 const colors=['#df9e86','#8eb6a6','#e1be73'],names=['圆形','三角形','方形'],friends=['小兔','小猫','小熊'];
 const icons={home:'<path d="m3 11 9-8 9 8M6 10v11h12V10M10 21v-7h4v7"/>',sound:'<path d="M4 9h4l5-5v16l-5-5H4ZM17 8q4 4 0 8M20 4q7 8 0 16"/>',replay:'<path d="M5 8a8 8 0 1 1-1 9M5 3v6h6"/>'};
 const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[name]}</svg>`;
 const hand='<span class="hint-hand"><svg viewBox="0 0 38 42"><path d="M13 20V7q0-5 5-5t5 5v12q4-6 7-2 5-1 5 5v9q0 10-11 10h-3q-7 0-12-9l-6-9q-3-5 2-6 3-1 8 7Z"/></svg></span>';
 const drop='<svg viewBox="0 0 40 45"><path d="M20 3C15 14 7 20 7 29a13 13 0 0 0 26 0C33 20 25 14 20 3Z" fill="#9bc7cf"/><path d="M14 28q-2 6 4 8" fill="none" stroke="#ecfaf6" stroke-width="3" stroke-linecap="round"/></svg>';
 function shape(i,face=true){const geom=['<circle class="shape" cx="50" cy="50" r="39"/>','<path class="shape" d="M45 11q5-8 10 0l38 69q5 9-6 9H13q-11 0-6-9Z"/>','<rect class="shape" x="12" y="12" width="76" height="76" rx="15"/>'][i];return `<svg viewBox="0 0 100 100" aria-hidden="true" style="fill:${colors[i]}">${geom}${face?'<g fill="#516955"><circle cx="38" cy="51" r="3"/><circle cx="62" cy="51" r="3"/><path d="M43 62q7 7 14 0" fill="none" stroke="#516955" stroke-width="2.5" stroke-linecap="round"/></g>':''}</svg>`;}
 function animal(i,earsOnly=false){let ears=['<ellipse cx="76" cy="65" rx="13" ry="37" fill="#f9ecd6"/><ellipse cx="124" cy="65" rx="13" ry="37" fill="#f9ecd6"/><ellipse cx="76" cy="62" rx="6" ry="25" fill="#e9bca6"/><ellipse cx="124" cy="62" rx="6" ry="25" fill="#e9bca6"/>','<path d="m57 99 2-57 34 34M108 76l34-34 2 57" fill="#dfb486"/><path d="m64 80 1-25 17 18m37 0 16-18 2 25" fill="#efc9ae"/>','<circle cx="65" cy="80" r="24" fill="#b9977f"/><circle cx="135" cy="80" r="24" fill="#b9977f"/><circle cx="65" cy="80" r="13" fill="#dcc3a7"/><circle cx="135" cy="80" r="13" fill="#dcc3a7"/>'][i];if(earsOnly)return ears;return `${ears}<ellipse cx="100" cy="197" rx="42" ry="42" fill="${['#a5bfa0','#e3aa87','#97b3b0'][i]}"/><circle cx="100" cy="125" r="48" fill="${['#f9ecd6','#dfb486','#b9977f'][i]}"/><ellipse cx="100" cy="139" rx="24" ry="17" fill="${['#fff6e6','#f4d8b5','#dcc3a7'][i]}"/><circle cx="83" cy="121" r="3.5" fill="#5b594e"/><circle cx="117" cy="121" r="3.5" fill="#5b594e"/><path d="m95 132 5 5 5-5Z" fill="#8d7262"/><path d="M100 137q-1 10-9 5m9-5q1 10 9 5" stroke="#8d7262" stroke-width="2" fill="none" stroke-linecap="round"/><ellipse cx="70" cy="136" rx="8" ry="5" fill="#dfa990" opacity=".6"/><ellipse cx="130" cy="136" rx="8" ry="5" fill="#dfa990" opacity=".6"/><path d="M68 184l-15 17m79-17 15 17" stroke="${['#f9ecd6','#dfb486','#b9977f'][i]}" stroke-width="15" stroke-linecap="round"/><path d="M87 235h-12m38 0h12" stroke="${['#f9ecd6','#dfb486','#b9977f'][i]}" stroke-width="16" stroke-linecap="round"/>`;}
 function plant(i,n){const petals=Array.from({length:6},(_,j)=>`<ellipse cx="100" cy="73" rx="17" ry="29" transform="rotate(${j*60} 100 100)" fill="${colors[i]}"/>`).join('');return `<svg viewBox="0 0 200 290" aria-hidden="true"><ellipse cx="100" cy="267" rx="68" ry="12" fill="#799872" opacity=".12"/><g class="growing">${n>0?`<path d="M100 224V${n===1?171:n===2?135:104}" stroke="#6f9a77" stroke-width="8" stroke-linecap="round"/><path d="M100 ${n===1?195:174}q-43-40-45-14 2 30 45 23M101 ${n===1?198:149}q42-36 45-10-8 28-45 20" fill="#93b287"/>`:''}${n===0?'<ellipse cx="100" cy="211" rx="13" ry="17" transform="rotate(-20 100 211)" fill="#b68d66"/><path d="m96 204 6 14" stroke="#d1ab7e" stroke-width="2"/>':''}${n===2?`<ellipse cx="100" cy="125" rx="16" ry="21" fill="${colors[i]}"/><path d="m88 129 12 9 12-9" fill="#7b9e79"/>`:''}${n===3?`<g class="bloom">${petals}<circle cx="100" cy="100" r="22" fill="#fff0b4"/><circle cx="93" cy="99" r="2.5" fill="#7d8156"/><circle cx="107" cy="99" r="2.5" fill="#7d8156"/><path d="M95 108q5 4 10 0" fill="none" stroke="#7d8156" stroke-width="2"/></g>`:''}</g><path d="M49 224h102l-13 43H62Z" fill="${['#d3a182','#c8b382','#9fb5a3'][i]}"/><rect x="43" y="215" width="114" height="17" rx="8" fill="${['#e2b697','#dbca9c','#b4c7b1'][i]}"/><ellipse cx="100" cy="216" rx="49" ry="8" fill="#9d8161"/><path d="M59 220h82" stroke="#ad9070" stroke-width="2"/><g class="droplets" fill="#91bdc9">${[60,92,126,145].map((x,j)=>`<path d="M${x} ${30+j*8}q-12 18 0 20 12-2 0-20Z"/>`).join('')}</g></svg>`;}
 function peek(i){const a=(i+state.round)%3;return `<svg viewBox="0 0 200 270" aria-hidden="true"><ellipse cx="100" cy="254" rx="88" ry="12" fill="#b8a285" opacity=".18"/><path d="M12 252V108a88 88 0 0 1 176 0v144Z" fill="#d4b893"/><path d="M23 243V108a77 77 0 0 1 154 0v135Z" fill="#f9efda"/><g class="friend">${animal(a)}</g><g class="peek-ears">${animal(a,true)}</g><g class="curtain"><path d="M20 103h160v139q-15 12-29 0-16 12-32 0-18 12-35 0-17 12-32 0-18 12-32 0Z" fill="${['#9cb8a1','#d5ab8d','#a6b9bc'][i]}"/><path d="M40 104v125m30-125v128m30-128v125m30-125v128m30-128v125" stroke="#fff8dc" stroke-width="4" opacity=".27"/><path d="M15 101h170" stroke="#ad8b65" stroke-width="10" stroke-linecap="round"/><g class="knob"><circle cx="100" cy="184" r="21" fill="#fff8e8"/><path d="m92 184 8-8 8 8m-8-8v18" fill="none" stroke="#9ba384" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></g></g></svg>`;}
 function stopVoice(){try{window.speechSynthesis?.cancel();}catch(_){}}
 function speak(text){lastVoice=text;if(muted||!window.speechSynthesis||!window.SpeechSynthesisUtterance)return;stopVoice();try{const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=.82;const voice=speechSynthesis.getVoices().find(v=>/^zh(-|_)/i.test(v.lang));if(voice)u.voice=voice;speechSynthesis.speak(u);}catch(_){}}
 function audio(){if(muted)return;try{const C=window.AudioContext||window.webkitAudioContext;if(C&&!context)context=new C();context?.resume()?.catch(()=>{});}catch(_){}}
 function tone(index=0,celebrate=false){if(muted)return;audio();if(!context)return;try{const t=context.currentTime;[0,...(celebrate?[4,7]:[])].forEach((n,j)=>{const osc=context.createOscillator(),g=context.createGain();osc.type='sine';osc.frequency.value=392*Math.pow(2,(index*2+n)/12);g.gain.setValueAtTime(0,t+j*.15);g.gain.linearRampToValueAtTime(.07,t+j*.15+.015);g.gain.exponentialRampToValueAtTime(.001,t+j*.15+.4);osc.connect(g);g.connect(context.destination);osc.start(t+j*.15);osc.stop(t+j*.15+.42);});}catch(_){}}
 const prompts={shapes:['点点积木，再点一样的空位。也可以拖过去。','找一找，一样的形状。'],garden:['点点花盆，让小种子喝点水。','小花慢慢长大啦。'],peekaboo:['谁藏起来了？点点帘子，或者向上拉开。','小耳朵，藏在哪里？']};
 const ending={shapes:['都回家啦！','小积木，谢谢你。'],garden:['花儿都开啦！','谢谢你照顾小花园。'],peekaboo:['大家都来啦！','你好呀，我的小伙伴。']};
 function confetti(){ $('celebration').innerHTML=Array.from({length:12},(_,i)=>`<span style="left:${8+i*7.5}%;top:${40+i%3*16}%;animation-delay:${i%4*.08}s">${i%2?'✦':'○'}</span>`).join('');}
 function feedback(text,small){$('status').innerHTML=`${text}<small>${small}</small>`;}
 function update(){
  const complete=done(state);$('intro').hidden=state.started;$('world').inert=!state.started;$('world').setAttribute('aria-hidden',String(!state.started));$('listen').disabled=!state.started;$('replay').hidden=!complete;
  [...$('progress').children].forEach((el,i)=>el.classList.toggle('done',state.values[i]===(kind==='garden'?3:1)));
  if(kind==='shapes'){
   document.querySelectorAll('.shape-piece').forEach((el,i)=>{el.classList.toggle('placed',!!state.values[i]);el.classList.toggle('selected',state.selected===i);el.disabled=!!state.values[i];el.setAttribute('aria-pressed',String(state.selected===i));});
   document.querySelectorAll('.shape-slot').forEach((el,i)=>{el.classList.toggle('filled',!!state.values[i]);el.classList.toggle('target',!complete&&i===state.selected);el.disabled=!!state.values[i];el.innerHTML=shape(i,!!state.values[i]);});
  }else if(kind==='garden'){
   document.querySelectorAll('.flower-pot').forEach((el,i)=>{const prev=el.dataset.growth;if(prev!==String(state.values[i])){el.innerHTML=plant(i,state.values[i])+`<span class="tap-badge">${drop}</span>`;el.dataset.growth=state.values[i];el.classList.toggle('watered',state.values[i]>0);}el.classList.toggle('bloomed',state.values[i]===3);el.disabled=state.values[i]===3;el.setAttribute('aria-label',`${['左边','中间','右边'][i]}的小花${state.values[i]===3?'已经开花':'，浇点水'}`);});
  }else document.querySelectorAll('.peek-door').forEach((el,i)=>{el.classList.toggle('revealed',!!state.values[i]);el.disabled=!!state.values[i];el.setAttribute('aria-label',state.values[i]?`${friends[(i+state.round)%3]}出来了`:`打开${['左边','中间','右边'][i]}的帘子`);});
  if(complete)feedback(...ending[kind]);
  window.littleGameState=Object.freeze({...state,values:Object.freeze(state.values.slice()),muted});
 }
 function build(){
  const world=$('world');
  if(kind==='shapes'){world.className='game-world shape-world';world.innerHTML=`<div class="visual-instruction" aria-hidden="true">${hand}<span class="mini">${shape(0)}</span><span class="flow-arrow">→</span><span class="mini">${shape(0,false)}</span></div><div class="shape-board" aria-label="三个形状的家">${[0,1,2].map(i=>`<button class="shape-slot" data-slot="${i}" aria-label="${names[i]}的家">${shape(i,false)}</button>`).join('')}</div><div class="shape-row" aria-label="选择小积木">${[0,1,2].map(i=>`<button class="shape-piece" data-piece="${i}" aria-label="拿起${names[i]}积木" aria-pressed="false">${shape(i)}</button>`).join('')}</div>`;
  }else if(kind==='garden'){world.className='game-world garden-world';world.innerHTML=`<div class="visual-instruction" aria-hidden="true">${hand}<span class="mini">${drop}</span><span class="flow-arrow">→</span><span class="mini"><svg viewBox="55 55 90 90">${plant(0,3).match(/<g class="bloom">([\s\S]*?)<\/g>/)[1]}</svg></span></div><div class="garden-bed">${[0,1,2].map(i=>`<button class="flower-pot" data-grow="${i}" aria-label="给小花浇水"></button>`).join('')}</div><div class="grass-edge" aria-hidden="true"></div>`;
  }else{world.className='game-world peek-world';world.innerHTML=`<div class="visual-instruction" aria-hidden="true">${hand}<span class="flow-arrow">↑</span><span class="mini"><svg viewBox="40 28 120 145">${animal(state.round%3)}</svg></span></div><div class="peek-row">${[0,1,2].map(i=>`<button class="peek-door" data-reveal="${i}" aria-label="打开帘子">${peek(i)}</button>`).join('')}</div>`;}
  update();
 }
 function act(type,index){
  if(!state.started)return;const before=state,complete=done(before);state=reduce(state,{type,index});update();
  if(type==='select'){speak(`把${names[index]}送到一样的空位。`);return;}
  if(!complete&&done(state)){tone(1,true);speak(ending[kind].join(''));confetti();return;}
  if(state.values.some((v,i)=>v!==before.values[i])){tone(index);let msg=kind==='shapes'?`${names[index]}回家啦。`:kind==='garden'?['','小芽冒出来啦。','叶子长大啦。','花儿开啦。'][state.values[index]]:`你好，${friends[(index+state.round)%3]}。`;feedback(msg,kind==='shapes'?'再找找下一个小积木。':kind==='garden'?'点点花盆，继续照顾它。':'再和旁边的小伙伴打个招呼。');speak(msg);}
  else if(type==='place'&&!complete){feedback('看看发亮的那个家。','慢慢来，再试一试就好。');speak('找找一样的形状。');}
 }
 function clearDrag(){if(drag){drag.el.style.transform='';drag.el.classList.remove('dragging');try{drag.el.releasePointerCapture(drag.id);}catch(_){}drag=null;}}
 $('world').addEventListener('click',e=>{if(suppressClick){suppressClick=false;return;}const b=e.target.closest('button');if(!b||b.disabled)return;audio();if(b.dataset.piece!==undefined)act('select',+b.dataset.piece);if(b.dataset.slot!==undefined)act('place',+b.dataset.slot);if(b.dataset.grow!==undefined)act('grow',+b.dataset.grow);if(b.dataset.reveal!==undefined)act('reveal',+b.dataset.reveal);});
 $('world').addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!state.started||!b||b.disabled||drag||swipe||e.button>0)return;if(b.dataset.piece!==undefined){audio();state=reduce(state,{type:'select',index:+b.dataset.piece});update();drag={el:b,id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};b.setPointerCapture(e.pointerId);}else if(b.dataset.reveal!==undefined){swipe={el:b,id:e.pointerId,y:e.clientY};b.setPointerCapture(e.pointerId);}});
 $('world').addEventListener('pointermove',e=>{if(drag&&drag.id===e.pointerId){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>8)drag.moved=true;if(drag.moved){drag.el.classList.add('dragging');drag.el.style.transform=`translate(${dx}px,${dy}px)`;}}});
 $('world').addEventListener('pointerup',e=>{if(drag&&drag.id===e.pointerId){const moved=drag.moved;clearDrag();if(moved){suppressClick=true;const hit=[...document.querySelectorAll('[data-slot]')].find(el=>{const r=el.getBoundingClientRect();return e.clientX>=r.left-14&&e.clientX<=r.right+14&&e.clientY>=r.top-14&&e.clientY<=r.bottom+14;});if(hit)act('place',+hit.dataset.slot);setTimeout(()=>suppressClick=false,0);}}if(swipe&&swipe.id===e.pointerId){const s=swipe;swipe=null;if(s.y-e.clientY>20){suppressClick=true;act('reveal',+s.el.dataset.reveal);setTimeout(()=>suppressClick=false,0);}}});
 $('world').addEventListener('pointercancel',e=>{if(drag?.id===e.pointerId)clearDrag();if(swipe?.id===e.pointerId)swipe=null;});
 window.addEventListener('resize',()=>{clearDrag();swipe=null;});
 $('start').addEventListener('click',()=>{state=reduce(state,{type:'start'});audio();update();feedback(prompts[kind][1],'看着图画，慢慢来。');speak(prompts[kind][0]);const first=$('world').querySelector('button:not(:disabled)');first?.focus({preventScroll:true});});
 $('replay').addEventListener('click',()=>{clearDrag();swipe=null;state=reduce(state,{type:'reset'});$('celebration').innerHTML='';build();feedback(prompts[kind][1],'又是一个新的小发现。');speak(prompts[kind][0]);$('world').querySelector('button:not(:disabled)')?.focus({preventScroll:true});});
 $('listen').addEventListener('click',()=>{audio();speak(done(state)?ending[kind].join(''):prompts[kind][0]);});
 try{muted=localStorage.getItem('littleHandsMuted')==='true';}catch(_){}
 function setSound(){ $('sound').setAttribute('aria-pressed',String(muted));$('sound').setAttribute('aria-label',muted?'打开声音':'关闭声音');$('soundText').textContent=muted?'声音关':'声音开';$('sound').style.opacity=muted?'.7':'1';update();}
 $('sound').addEventListener('click',()=>{muted=!muted;try{localStorage.setItem('littleHandsMuted',String(muted));}catch(_){}if(muted){stopVoice();context?.suspend()?.catch(()=>{});}else{audio();if(state.started)speak(lastVoice||prompts[kind][0]);}setSound();});
 document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
 $('introArt').innerHTML=kind==='shapes'?`<svg viewBox="0 0 180 115"><g transform="translate(0 15) scale(.8)">${shape(0).replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g transform="translate(92 12) scale(.8)">${shape(1).replace(/<svg[^>]*>|<\/svg>/g,'')}</g></svg>`:kind==='garden'?plant(0,3):`<svg viewBox="25 15 150 240">${animal(0)}</svg>`;
 build();setSound();
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stopVoice();clearDrag();swipe=null;context?.suspend()?.catch(()=>{});}});
 window.addEventListener('pagehide',()=>{stopVoice();clearDrag();context?.suspend()?.catch(()=>{});});
})();
